def vhd_table(name, typ, depth, width, vals, signed=False):
    lines = ["    type %s is array (0 to %d) of %s(%d downto 0);" % ("t_" + name.lower(), depth - 1, typ, width - 1),
             "    constant %s : %s := (" % (name, "t_" + name.lower())]
    items = []
    for v in vals:
        if signed:
            items.append('to_signed(%d, %d)' % (v, width))
        elif width % 4 == 0:
            items.append('x"%0*X"' % (width // 4, v))
        else:
            items.append('to_unsigned(%d, %d)' % (v, width))
    per = 8 if (signed or width % 4) else 16
    for i in range(0, len(items), per):
        lines.append("        " + ", ".join(items[i:i + per]) + ("," if i + per < len(items) else ""))
    lines.append("    );")
    return "\n".join(lines)

def main():
    parts = ["-- Generated by grotto.py -- DO NOT EDIT.",
             "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
             "package grotto_pkg is",
             vhd_table("C_GR_TAB", "unsigned", 4096, 10, TAB),
             vhd_table("C_GR_PAL", "std_logic_vector", 512, 24, PAL),
             vhd_table("C_GR_SPEC", "std_logic_vector", 4, 24, SPEC),
             vhd_table("C_GR_BXE", "unsigned", 256, 8, BXE),
             vhd_table("C_GR_BXS", "unsigned", 256, 8, BXS),
             vhd_table("C_GR_SIN", "signed", 256, 8, SIN, signed=True),
             vhd_table("C_GR_EXP2", "unsigned", 256, 16, EXP2),
             "end package grotto_pkg;", ""]
    with open(os.path.join(HERE, "grotto_pkg.vhd"), "w") as f:
        f.write("\n".join(parts))

if __name__ == "__main__":
    main()
